const raw = $input.first().json;
const i = raw.body || raw;
const order_id = Number(i.order_id||i.orderId||0);
return [{ json: { order_id, status: (i.status||'').toLowerCase(), tracking_number: i.tracking_number||i.trackingNumber||null, carrier: i.carrier||null, estimated_delivery: i.estimated_delivery||null, store_id: i.store_id||1 } }];

const norm = $('Normalize').first().json;
const order = $input.first().json;
const store_id = order.store_id || norm.store_id || 1;
const order_number = order.order_number || 'N/A';
const status = norm.status;
const order_id = norm.order_id;
let action_sql = '';
if (status === 'delivered') {
  action_sql = `INSERT INTO review_requests (store_id, order_id, customer_id, token, status, scheduled_at, expires_at, created_at) SELECT o.store_id, o.id, o.customer_id, md5(random()::text || o.id::text), 'SCHEDULED', NOW() + INTERVAL '7 days', NOW() + INTERVAL '30 days', NOW() FROM orders o WHERE o.id = ${order_id} AND NOT EXISTS (SELECT 1 FROM review_requests rr WHERE rr.order_id = o.id);`;
} else if (status === 'delayed') {
  action_sql = `INSERT INTO alerts (store_id, type, severity, message, is_read, is_sent, created_at) VALUES (${store_id}, 'ORDER_DELAYED', 'high', 'Commande #${order_number} retardee', false, false, NOW());`;
} else if (status === 'cancelled') {
  action_sql = `INSERT INTO alerts (store_id, type, severity, message, is_read, is_sent, created_at) VALUES (${store_id}, 'ORDER_CANCELLED', 'medium', 'Commande #${order_number} annulee', false, false, NOW());`;
}
return [{ json: { order_id, status, store_id, order_number, action_sql } }];
